# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e293b">PERİYODİK SİSTEMİN TARİHÇESİ — BİLİM İNSANLARININ KATKILARI</text>\n  <rect x="15" y="44" width="128" height="196" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="79" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">1. Döbereiner (1829)</text>\n  <text x="79" y="92" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e3a8a">Üçlü Gruplar (Triadlar)</text>\n  <text x="79" y="116" text-anchor="middle" font-size="10" fill="#334155">Benzer özellik gösteren</text>\n  <text x="79" y="132" text-anchor="middle" font-size="10" fill="#334155">elementleri üçerli</text>\n  <text x="79" y="148" text-anchor="middle" font-size="10" fill="#334155">gruplar halinde dizdi.</text>\n  <text x="79" y="176" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Örnek: Li - Na - K</text>\n  <text x="79" y="198" text-anchor="middle" font-size="9" fill="#475569">İlk sınıflandırma</text>\n  <text x="79" y="212" text-anchor="middle" font-size="9" fill="#475569">çalışmasını yaptı.</text>\n\n  <rect x="153" y="44" width="128" height="196" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="217" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">2. Newlands (1864)</text>\n  <text x="217" y="92" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">Oktavlar (Sekizliler)</text>\n  <text x="217" y="116" text-anchor="middle" font-size="10" fill="#334155">Bilinen 62 elementi</text>\n  <text x="217" y="132" text-anchor="middle" font-size="10" fill="#334155">artan atom ağırlığına</text>\n  <text x="217" y="148" text-anchor="middle" font-size="10" fill="#334155">göre sıraladı.</text>\n  <text x="217" y="176" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Müzik Notası Benzetmesi</text>\n  <text x="217" y="198" text-anchor="middle" font-size="9" fill="#475569">İlk 8 elementten sonra</text>\n  <text x="217" y="212" text-anchor="middle" font-size="9" fill="#475569">özelliklerin tekrarlandığını gördü.</text>\n\n  <rect x="291" y="44" width="132" height="196" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="357" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">3. Mendeleyev &amp; Meyer</text>\n  <text x="357" y="92" text-anchor="middle" font-size="10" font-weight="bold" fill="#854d0e">Kütle Numarası (Ağırlık)</text>\n  <text x="357" y="116" text-anchor="middle" font-size="10" fill="#334155">Mendeleyev artan atom</text>\n  <text x="357" y="132" text-anchor="middle" font-size="10" fill="#334155">ağırlığına göre dizdi;</text>\n  <text x="357" y="148" text-anchor="middle" font-size="10" fill="#334155">keşfedilmemiş yerleri</text>\n  <text x="357" y="164" text-anchor="middle" font-size="10" fill="#334155">boş bırakıp tahmin etti.</text>\n  <text x="357" y="190" text-anchor="middle" font-size="10" font-weight="bold" fill="#a16207">Periyodik Tablonun Babası</text>\n  <text x="357" y="212" text-anchor="middle" font-size="9" fill="#475569">Meyer fiziksel özelliklere baktı.</text>\n\n  <rect x="433" y="44" width="124" height="196" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="495" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">4. H. Moseley (1913)</text>\n  <text x="495" y="92" text-anchor="middle" font-size="10" font-weight="bold" fill="#6b21a8">Atom Numarası (Proton)</text>\n  <text x="495" y="116" text-anchor="middle" font-size="10" fill="#334155">Elementleri artan atom</text>\n  <text x="495" y="132" text-anchor="middle" font-size="10" fill="#334155">ağırlığına değil, artan</text>\n  <text x="495" y="148" text-anchor="middle" font-size="10" font-weight="bold" fill="#6b21a8">PROTON SAYISINA</text>\n  <text x="495" y="164" text-anchor="middle" font-size="10" fill="#334155">(atom no) göre dizdi.</text>\n  <text x="495" y="190" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">Modern Tablo Temeli</text>\n  <text x="495" y="212" text-anchor="middle" font-size="9" fill="#475569">Sıralama hatalarını giderdi.</text>\n\n  <rect x="567" y="44" width="118" height="196" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="626" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">5. G. Seaborg</text>\n  <text x="626" y="92" text-anchor="middle" font-size="10" font-weight="bold" fill="#9f1239">Son Şeklini Verdi</text>\n  <text x="626" y="116" text-anchor="middle" font-size="10" fill="#334155">Tablonun altına iki</text>\n  <text x="626" y="132" text-anchor="middle" font-size="10" fill="#334155">yatay sıra (Lantanit</text>\n  <text x="626" y="148" text-anchor="middle" font-size="10" fill="#334155">ve Aktinitler) ekleyerek</text>\n  <text x="626" y="164" text-anchor="middle" font-size="10" fill="#334155">günümüzdeki son</text>\n  <text x="626" y="180" text-anchor="middle" font-size="10" fill="#334155">halini kazandırdı.</text>\n  <text x="626" y="206" text-anchor="middle" font-size="10" font-weight="bold" fill="#be123c">Alt 2 Satır Eklendi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e293b">PERİYOT VE GRUP ÖZELLİKLERİ — SOLDAN SAĞA VE YUKARIDAN AŞAĞIYA DEĞİŞİM</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">Periyot (7 Yatay Sıra) ve Grup (18 Düşey Sütun)</text>\n  <text x="180" y="90" text-anchor="middle" font-size="11" fill="#164e63">• Katman (yörünge) sayısı = PERİYOT numarası</text>\n  <text x="180" y="110" text-anchor="middle" font-size="11" fill="#164e63">• Son katman elektron sayısı = A GRUBU numarası</text>\n  <text x="180" y="130" text-anchor="middle" font-size="11" fill="#164e63">• Toplam 18 grup: 8 tanesi A grubu, 10 tanesi B grubu</text>\n  <text x="180" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Örnek: ₁₂Mg → 2 ) 8 ) 2 → 3. Periyot, 2A Grubu</text>\n  <text x="180" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">İstisna 1: ₂He → 2 ) → 1. Periyot, 8A Grubu (2A değil!)</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">İstisna 2: ₁H → 1 ) → 1. Periyot, 1A Grubu (Ametal!)</text>\n  <text x="180" y="220" text-anchor="middle" font-size="10" fill="#155e75">Aynı gruptaki elementlerin kimyasal özellikleri benzerdir (H hariç).</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">Periyodik Tabloda Değişen Özellikler</text>\n  <text x="520" y="92" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Aynı Periyotta Soldan Sağa Doğru (→):</text>\n  <text x="520" y="112" text-anchor="middle" font-size="11" fill="#78350f">• Atom numarası (proton sayısı) ve kütle numarası ARTAR.</text>\n  <text x="520" y="130" text-anchor="middle" font-size="11" fill="#78350f">• Katman sayısı DEĞİŞMEZ, grup numarası (değerlik e⁻) ARTAR.</text>\n  <text x="520" y="148" text-anchor="middle" font-size="11" fill="#78350f">• Atom hacmi (çapı) AZALIR, ametalik özellik ARTAR.</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Aynı Grupta Yukarıdan Aşağıya Doğru (↓):</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11" fill="#78350f">• Atom numarası, kütle no ve katman sayısı ARTAR.</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" fill="#78350f">• Son katman elektron sayısı DEĞİŞMEZ (He hariç).</text>\n  <text x="520" y="228" text-anchor="middle" font-size="11" fill="#78350f">• Atom hacmi (çapı) ve metalik özellik ARTAR.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e293b">ELEMENTLERİN SINIFLANDIRILMASI: METAL · YARI METAL · AMETAL · SOY GAZ</text>\n  <rect x="15" y="44" width="160" height="196" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="95" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. METALLER</text>\n  <text x="95" y="88" text-anchor="middle" font-size="10" fill="#1e3a8a">• Tablonun sol ve orta kısmı</text>\n  <text x="95" y="106" text-anchor="middle" font-size="10" fill="#1e3a8a">• Yüzeyleri parlaktır</text>\n  <text x="95" y="124" text-anchor="middle" font-size="10" fill="#1e3a8a">• Isı ve elektriği iyi iletir</text>\n  <text x="95" y="142" text-anchor="middle" font-size="10" fill="#1e3a8a">• Tel ve levha haline gelir</text>\n  <text x="95" y="160" text-anchor="middle" font-size="10" fill="#1e3a8a">• Cıva (Hg) hariç katıdır</text>\n  <text x="95" y="178" text-anchor="middle" font-size="10" fill="#1e3a8a">• Atomik yapılıdır</text>\n  <text x="95" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Metaller kendi aralarında</text>\n  <text x="95" y="214" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">bileşik yapmaz, ALAŞIM yapar</text>\n\n  <rect x="185" y="44" width="160" height="196" rx="8" fill="#fef9c3" stroke="#ca8a04" stroke-width="1.5"/>\n  <text x="265" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">2. YARI METALLER</text>\n  <text x="265" y="88" text-anchor="middle" font-size="10" fill="#713f12">• Metal-ametal sınırında</text>\n  <text x="265" y="106" text-anchor="middle" font-size="10" fill="#713f12">• Oda sıcaklığında katıdır</text>\n  <text x="265" y="124" text-anchor="middle" font-size="10" fill="#713f12">• Parlak veya mat olabilir</text>\n  <text x="265" y="142" text-anchor="middle" font-size="10" fill="#713f12">• İşlenebilir (kırılgan değil)</text>\n  <text x="265" y="160" text-anchor="middle" font-size="10" fill="#713f12">• Elektriği ametallerden iyi,</text>\n  <text x="265" y="176" text-anchor="middle" font-size="10" fill="#713f12">metallerden az iletir</text>\n  <text x="265" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#a16207">Fiziksel: Metal · Kimyasal: Ametal</text>\n  <text x="265" y="216" text-anchor="middle" font-size="10" font-weight="bold" fill="#854d0e">Örnek: Bor (B), Silisyum (Si)</text>\n\n  <rect x="355" y="44" width="160" height="196" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="435" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. AMETALLER</text>\n  <text x="435" y="88" text-anchor="middle" font-size="10" fill="#14532d">• Sağ tarafta (1A\'daki H hariç)</text>\n  <text x="435" y="106" text-anchor="middle" font-size="10" fill="#14532d">• Yüzeyleri mattır</text>\n  <text x="435" y="124" text-anchor="middle" font-size="10" fill="#14532d">• Isı ve elektriği iyi iletmez</text>\n  <text x="435" y="142" text-anchor="middle" font-size="10" fill="#14532d">• Katı olanları kırılgandır</text>\n  <text x="435" y="160" text-anchor="middle" font-size="10" fill="#14532d">• Katı, sıvı, gaz olabilir</text>\n  <text x="435" y="178" text-anchor="middle" font-size="10" fill="#14532d">• Molekül yapılıdır</text>\n  <text x="435" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Hem metallerle hem kendi</text>\n  <text x="435" y="214" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">aralarında BİLEŞİK yapar (H, C, O)</text>\n\n  <rect x="525" y="44" width="160" height="196" rx="8" fill="#f3e8ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="605" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">4. SOY GAZLAR (8A)</text>\n  <text x="605" y="88" text-anchor="middle" font-size="10" fill="#581c87">• Ametallerin 8A özel grubu</text>\n  <text x="605" y="106" text-anchor="middle" font-size="10" fill="#581c87">• Tamamı oda sıcaklığında GAZ</text>\n  <text x="605" y="124" text-anchor="middle" font-size="10" fill="#581c87">• Kararlı yapılıdır</text>\n  <text x="605" y="142" text-anchor="middle" font-size="10" fill="#581c87">• Elektron almaz/vermez</text>\n  <text x="605" y="160" text-anchor="middle" font-size="10" fill="#581c87">• Bileşik oluşturmaz</text>\n  <text x="605" y="178" text-anchor="middle" font-size="10" fill="#581c87">• Tek atomlu gazlardır</text>\n  <text x="605" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">He (son katman 2 e⁻),</text>\n  <text x="605" y="214" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">Ne, Ar (son katman 8 e⁻)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
